attributes.onClick:
() => {
        navigator.clipboard.writeText(code).catch(() => undefined);
        const el = document.activeElement as HTMLButtonElement;
        const orig = el.textContent ?? '';
        el.textContent = `✓ ${t('copied')}`;
        setTimeout(() => { el.textContent = orig; }, 2000);
      }

